"""V2 image-only semantics: local overlap and relative ankle height, no coordinates."""
import extract
BASE=extract.map_conditions
extract.PROMPT += '''\nAdditional required fields: In each leg include "ankle_height_vs_other_knee":"above|near|below|uncertain", "height_confidence":"clear|weak", and "knee_position_vs_own_hip":"above|near|below|uncertain". These describe screen vertical position, NOT 3D knee flexion. A raised heel behind a straight thigh can mean a folded calf, not a thigh lifted toward the chest. Do not infer a raised thigh from a high shoe. Give each occlusion_junction a "front_segment" and "back_segment" chosen from thigh|shin|foot|uncertain, and "along_front" and "along_back" chosen from proximal|middle|distal|uncertain. These are local relations at that junction, never whole-leg depth ordering. Only mark clear when a visible contour actually supports the relation. Partial occlusion must identify which shoe portion is hidden and which remains visible in evidence. When an ankle is visible but overlaps another leg, do not label it cropped. Never give coordinates or desired numeric angles.'''
def mapping(raw,obs,digest,observation_hash):
 c=BASE(raw,obs,digest,observation_hash);c['schema_version']=2;c['ankle_height_evidence']={c['mapping'][l['hip_position']]:{k:l.get(k,'uncertain') for k in ['ankle_height_vs_other_knee','height_confidence','knee_position_vs_own_hip']} for l in raw.get('legs',[]) if l.get('hip_position') in c['mapping']};c['local_occlusions']=[dict(near=c['mapping'].get(j.get('front_hip')),far=c['mapping'].get(j.get('back_hip')),front_segment=j.get('front_segment','uncertain'),back_segment=j.get('back_segment','uncertain'),along_front=j.get('along_front','uncertain'),along_back=j.get('along_back','uncertain')) for j in raw.get('occlusion_junctions',[])];return c
extract.map_conditions=mapping
if __name__=='__main__':extract.main()
